package com.theone.tv.phone;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;
public class ChannelCatalogTest {
 private CatalogEntry entry(int id,String title,String country){return new CatalogEntry(id,title,"m3u8","",country,"live",0);}
 @Test public void countriesSortNetherlandsThenUsThenEngland(){List<CatalogEntry> list=new ArrayList<>(Arrays.asList(entry(1,"FR - TF1","FR"),entry(2,"UK - BBC One","GB"),entry(3,"US - CNN","US"),entry(4,"NL - NPO 1","NL")));list.sort(CatalogEntry.CHANNEL_ORDER);assertEquals(Arrays.asList("NL","US","GB","FR"),Arrays.asList(list.get(0).category,list.get(1).category,list.get(2).category,list.get(3).category));}
 @Test public void duplicatesAcrossSourcesAndQualityHaveOneTileAndBackups(){List<CatalogEntry> rows=Arrays.asList(entry(1,"NL | NPO 1 HD","NL"),entry(1000000002,"NL: NPO1 FHD","NL"),entry(3,"NL - NPO 1 4K","NL"));Map<String,List<CatalogEntry>> groups=CatalogEntry.group(rows);assertEquals(1,groups.size());List<CatalogEntry> variants=groups.values().iterator().next();assertEquals(3,variants.size());assertEquals(2160,variants.get(0).rank);}
 @Test public void countriesAndTimeShiftChannelsRemainSeparate(){assertNotEquals(entry(1,"US - ESPN","US").key(),entry(2,"UK - ESPN","GB").key());assertNotEquals(entry(1,"UK - Channel 4","GB").key(),entry(2,"UK - Channel 4 +1","GB").key());}
 @Test public void numberedChannelsHaveNaturalOrder(){List<CatalogEntry> rows=new ArrayList<>(Arrays.asList(entry(10,"NL - ESPN 10","NL"),entry(2,"NL - ESPN 2","NL"),entry(1,"NL - ESPN 1","NL")));rows.sort(CatalogEntry.CHANNEL_ORDER);assertEquals(1,rows.get(0).id);assertEquals(2,rows.get(1).id);assertEquals(10,rows.get(2).id);}
 @Test public void categoryNamesClassifyUntaggedChannels(){assertEquals("US",CatalogEntry.country("CNN","United States"));assertEquals("GB",CatalogEntry.country("BBC One","United Kingdom"));assertEquals("NL",CatalogEntry.country("NPO 1","Netherlands"));}
 @Test public void backupFormatsAndCountriesSurviveCache()throws Exception{List<CatalogEntry> rows=Arrays.asList(entry(1,"NL - NPO 1 HD","NL"),new CatalogEntry(1000000002,"NL - NPO 1 HD","ts","","NL","live",0));ByteArrayOutputStream out=new ByteArrayOutputStream();CatalogCodec.write(out,rows);List<CatalogEntry> saved=CatalogCodec.read(new ByteArrayInputStream(out.toByteArray()),"live");assertEquals(1,CatalogEntry.group(saved).size());assertEquals("ts",saved.get(1).extension);assertEquals("NL",saved.get(0).category);}
 @Test public void ultraHdChannelsFollowRegularChannelsWithinEachCountry(){List<CatalogEntry> rows=new ArrayList<>(Arrays.asList(entry(1,"NL - NPO 1 16K","NL"),entry(2,"NL - NPO 2 8K","NL"),entry(3,"NL - NPO 3 HD","NL"),entry(4,"NL - NPO 4 4K","NL"),entry(5,"BE - VRT 16K","BE"),entry(6,"BE - VRT HD","BE")));rows.sort(CatalogEntry.CHANNEL_ORDER);assertEquals(Arrays.asList(3,4,2,1,6,5),Arrays.asList(rows.get(0).id,rows.get(1).id,rows.get(2).id,rows.get(3).id,rows.get(4).id,rows.get(5).id));}
}
